referenceSolutions.javascript:
function parcelBudgetPeakTicket(drawers, k) {
  const a=drawers; let out=[];
  const dp=Array(k+1).fill(0);for(const [weight,value]of a)for(let c=k;c>=weight;c--)dp[c]=Math.max(dp[c],dp[c-weight]+value);out=dp;
  let answer=out.length?out[0]:0;for(const x of out)if(x>answer)answer=x;return answer;
}

